package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryParseOptions;
import org.eclipse.rdf4j.query.QueryParseOptions.GraphAlgebraMode;
import org.eclipse.rdf4j.query.algebra.Modify;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailUpdate;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class GraphAlgebraLegacySemanticsTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final List<GraphAlgebraMode> MODES = List.of(GraphAlgebraMode.LEGACY, GraphAlgebraMode.GRAPH);
	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		try (var connection = repository.getConnection()) {
			connection.add(iri("a"), iri("p"), iri("defaultObject"));
			connection.add(iri("a"), iri("p"), iri("b"), iri("g1"));
			connection.add(iri("b"), iri("p"), iri("c"), iri("g1"));
			connection.add(iri("a"), iri("mark"), VF.createLiteral("one"), iri("g1"));
			connection.add(iri("x"), iri("mark"), VF.createLiteral("wrong graph"), iri("g1"));
			connection.add(iri("x"), iri("p"), iri("y"), iri("g2"));
			connection.add(iri("y"), iri("p"), iri("z"), iri("g2"));
			connection.add(iri("c"), iri("p"), iri("d"), iri("g2"));
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void emptyGraphEnumeratesNamedContextsOnlyInGraphMode() {
		String text = "SELECT ?g WHERE { GRAPH ?g {} }";

		assertThat(query(text, GraphAlgebraMode.GRAPH))
				.containsExactlyInAnyOrder(Map.of("g", iri("g1")), Map.of("g", iri("g2")));
		assertThat(query(text, GraphAlgebraMode.LEGACY)).containsExactly(Map.of());
	}

	@Test
	void missingGraphWithOnlyBindRetainsTheLegacyExistenceLimitation() {
		String text = "SELECT ?x WHERE { GRAPH <urn:missing> { BIND(1 AS ?x) } }";

		assertThat(query(text, GraphAlgebraMode.GRAPH)).isEmpty();
		assertThat(query(text, GraphAlgebraMode.LEGACY)).singleElement().satisfies(row -> {
			assertThat(row.get("x").stringValue()).isEqualTo("1");
		});
	}

	@Test
	void ordinaryNamedTriplesAgreeAndExcludeTheDefaultGraph() {
		String text = "SELECT ?g ?s ?o WHERE { GRAPH ?g { ?s <urn:p> ?o } }";
		for (var mode : MODES) {
			assertThat(query(text, mode)).as(mode.toString())
					.containsExactlyInAnyOrder(
							Map.of("g", iri("g1"), "s", iri("a"), "o", iri("b")),
							Map.of("g", iri("g1"), "s", iri("b"), "o", iri("c")),
							Map.of("g", iri("g2"), "s", iri("x"), "o", iri("y")),
							Map.of("g", iri("g2"), "s", iri("y"), "o", iri("z")),
							Map.of("g", iri("g2"), "s", iri("c"), "o", iri("d")));
		}
	}

	@Test
	void legacyContextBindingIsVisibleInsideGraphWhileModernSelectorIsJoinedAfterwards() {
		String text = "SELECT ?g ?copy WHERE { GRAPH ?g { ?s <urn:p> ?o BIND(?g AS ?copy) } }";

		assertThat(query(text, GraphAlgebraMode.GRAPH)).hasSize(5).allSatisfy(row -> {
			assertThat(row).containsKey("g").doesNotContainKey("copy");
		});
		assertThat(query(text, GraphAlgebraMode.LEGACY)).hasSize(5).allSatisfy(row -> {
			assertThat(row).containsKey("g").containsKey("copy");
			assertThat(row.get("copy")).isEqualTo(row.get("g"));
		});
	}

	@Test
	void optionalAndExistsDoNotReadAnotherNamedGraph() {
		String text = "SELECT ?g ?s ?mark WHERE { GRAPH ?g { ?s <urn:p> ?o "
				+ "OPTIONAL { ?s <urn:mark> ?mark } FILTER EXISTS { ?o <urn:p> ?end } } }";
		for (var mode : MODES) {
			assertThat(query(text, mode)).as(mode.toString())
					.containsExactlyInAnyOrder(
							Map.of("g", iri("g1"), "s", iri("a"), "mark", VF.createLiteral("one")),
							Map.of("g", iri("g2"), "s", iri("x")));
		}
	}

	@Test
	void arbitraryLengthPathsStayWithinOneNamedGraph() {
		String text = "SELECT ?g ?end WHERE { GRAPH ?g { <urn:a> <urn:p>+ ?end } }";
		for (var mode : MODES) {
			assertThat(query(text, mode)).as(mode.toString())
					.containsExactlyInAnyOrder(
							Map.of("g", iri("g1"), "end", iri("b")),
							Map.of("g", iri("g1"), "end", iri("c")));
		}
	}

	@Test
	void explicitNamedDatasetRestrictsBothRepresentations() {
		String text = "SELECT ?g ?s ?o FROM NAMED <urn:g1> WHERE { GRAPH ?g { ?s <urn:p> ?o } }";
		for (var mode : MODES) {
			assertThat(query(text, mode)).as(mode.toString())
					.containsExactlyInAnyOrder(
							Map.of("g", iri("g1"), "s", iri("a"), "o", iri("b")),
							Map.of("g", iri("g1"), "s", iri("b"), "o", iri("c")));
		}
	}

	@Test
	void subqueryWithConstantGraphKeepsTheNamedContextInBothModes() {
		String text = "SELECT ?s WHERE { GRAPH <urn:g1> { SELECT ?s WHERE { ?s <urn:p> ?o } } }";
		for (var mode : MODES) {
			assertThat(query(text, mode)).as(mode.toString())
					.containsExactlyInAnyOrder(
							Map.of("s", iri("a")), Map.of("s", iri("b")));
		}
	}

	@Test
	void subqueryGraphSelectorIsLostByLegacyLoweringIfNotProjected() {
		String text = "SELECT ?g ?s WHERE { GRAPH ?g { SELECT ?s WHERE { ?s <urn:p> ?o } } }";

		assertThat(query(text, GraphAlgebraMode.GRAPH)).containsExactlyInAnyOrder(
				Map.of("g", iri("g1"), "s", iri("a")),
				Map.of("g", iri("g1"), "s", iri("b")),
				Map.of("g", iri("g2"), "s", iri("x")),
				Map.of("g", iri("g2"), "s", iri("y")),
				Map.of("g", iri("g2"), "s", iri("c")));
		assertThat(query(text, GraphAlgebraMode.LEGACY)).containsExactlyInAnyOrder(
				Map.of("s", iri("a")), Map.of("s", iri("b")), Map.of("s", iri("x")),
				Map.of("s", iri("y")), Map.of("s", iri("c")));
	}

	@Test
	void emptyGraphInUpdateWhereChangesWritesWhileTemplateKeepsItsContext() {
		String text = "INSERT { GRAPH <urn:copied> { ?g <urn:seen> true } } "
				+ "USING NAMED <urn:g1> USING NAMED <urn:g2> WHERE { GRAPH ?g {} }";
		try (var connection = repository.getConnection()) {
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.LEGACY));
			connection.prepareUpdate(text).execute();
			assertThat(connection.size(iri("copied"))).isZero();

			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.GRAPH));
			SailUpdate modern = (SailUpdate) connection.prepareUpdate(text);
			var modify = (Modify) modern.getParsedUpdate().getUpdateExprs().getFirst();
			assertThat(modify.getInsertExpr()).isInstanceOfSatisfying(StatementPattern.class, pattern -> {
				assertThat(pattern.getScope()).isEqualTo(StatementPattern.Scope.NAMED_CONTEXTS);
				assertThat(pattern.getContextVar().getValue()).isEqualTo(iri("copied"));
			});
			modern.execute();
			assertThat(connection.size(iri("copied"))).isEqualTo(2);
			assertThat(connection.hasStatement(iri("g1"), iri("seen"), VF.createLiteral(true), false, iri("copied")))
					.isTrue();
			assertThat(connection.hasStatement(iri("g2"), iri("seen"), VF.createLiteral(true), false, iri("copied")))
					.isTrue();
		}
	}

	private List<Map<String, Value>> query(String text, GraphAlgebraMode mode) {
		try (var connection = repository.getConnection()) {
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(mode));
			List<Map<String, Value>> rows = new ArrayList<>();
			try (var result = connection.prepareTupleQuery(text).evaluate()) {
				while (result.hasNext()) {
					Map<String, Value> row = new HashMap<>();
					result.next().forEach(binding -> row.put(binding.getName(), binding.getValue()));
					rows.add(Map.copyOf(row));
				}
			}
			return rows;
		}
	}

	private static IRI iri(String name) {
		return VF.createIRI("urn:" + name);
	}
}
